import { promises as fs } from "fs";
import path from "path";

export type BookStatus = "reading" | "finished";

export interface Book {
  id: string;
  title: string;
  author: string;
  status: BookStatus;
  notes: string;
  startedAt: string;
  finishedAt: string | null;
}

const dataFile = path.join(process.cwd(), "data", "books.json");

async function readAll(): Promise<Book[]> {
  try {
    const raw = await fs.readFile(dataFile, "utf-8");
    const parsed = JSON.parse(raw) as { books?: Book[] };
    return parsed.books ?? [];
  } catch {
    return [];
  }
}

async function writeAll(books: Book[]): Promise<void> {
  await fs.mkdir(path.dirname(dataFile), { recursive: true });
  await fs.writeFile(dataFile, JSON.stringify({ books }, null, 2) + "\n", "utf-8");
}

export async function getAllBooks(): Promise<Book[]> {
  return readAll();
}

export async function getBook(id: string): Promise<Book | null> {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function createBook(input: {
  title: string;
  author: string;
  notes: string;
}): Promise<Book> {
  const books = await readAll();
  const book: Book = {
    id: crypto.randomUUID(),
    title: input.title,
    author: input.author,
    status: "reading",
    notes: input.notes,
    startedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id: string): Promise<void> {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (book) {
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await writeAll(books);
  }
}

export async function updateNotes(id: string, notes: string): Promise<void> {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (book) {
    book.notes = notes;
    await writeAll(books);
  }
}

"use server";

import { createBook, markFinished, updateNotes } from "@/lib/books";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

export async function addBookAction(formData: FormData): Promise<void> {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();

  if (!title) {
    return;
  }

  const book = await createBook({ title, author, notes });
  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function markFinishedAction(formData: FormData): Promise<void> {
  const id = String(formData.get("id") ?? "");
  if (!id) return;

  await markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}

export async function saveNotesAction(formData: FormData): Promise<void> {
  const id = String(formData.get("id") ?? "");
  const notes = String(formData.get("notes") ?? "");
  if (!id) return;

  await updateNotes(id, notes);
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}

