import type { ReactNode } from "react";
import "./globals.css";

export const metadata = {
  title: "Books",
  description: "Keep track of the books I am reading.",
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  max-width: 640px;
  margin: 2rem auto;
  padding: 0 1rem;
  line-height: 1.6;
  color: #222;
}

a {
  color: #0066cc;
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

h1 {
  margin-bottom: 0.25rem;
}

section {
  margin: 2rem 0;
}

ul {
  list-style: none;
  padding: 0;
}

li {
  margin: 0.4rem 0;
}

label {
  display: block;
  margin: 0.75rem 0;
  font-weight: 600;
}

input,
textarea {
  display: block;
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.5rem;
  font: inherit;
  border: 1px solid #ccc;
  border-radius: 4px;
}

textarea {
  min-height: 140px;
  resize: vertical;
}

button {
  padding: 0.5rem 1rem;
  font: inherit;
  background: #0066cc;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
button:hover {
  background: #005bb5;
}

.muted {
  color: #888;
  font-weight: 400;
}

.back {
  display: inline-block;
  margin-bottom: 1rem;
}

import Link from "next/link";
import { getAllBooks } from "@/lib/books";

export const dynamic = "force-dynamic";

export default async function Home() {
  const books = await getAllBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return (
    <main>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
        <h1>Books</h1>
        <Link href="/books/new">+ Add a book</Link>
      </header>

      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="muted">Nothing right now.</p>
        ) : (
          <ul>
            {reading.map((b) => (
              <li key={b.id}>
                <Link href={`/books/${b.id}`}>{b.title}</Link>{" "}
                <span className="muted">— {b.author}</span>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="muted">Nothing yet.</p>
        ) : (
          <ul>
            {finished.map((b) => (
              <li key={b.id}>
                <Link href={`/books/${b.id}`}>{b.title}</Link>{" "}
                <span className="muted">— {b.author}</span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { markFinishedAction, saveNotesAction } from "@/app/actions";

export const dynamic = "force-dynamic";

interface PageProps {
  params: Promise<{ id: string }>;
}

export default async function BookPage({ params }: PageProps) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <main>
      <Link href="/" className="back">
        ← All books
      </Link>

      <h1>{book.title}</h1>
      <p className="muted">by {book.author}</p>
      <p>Status: {book.status}</p>

      {book.status === "reading" && (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark as finished</button>
        </form>
      )}

      <section>
        <h2>Notes</h2>
        <form action={saveNotesAction}>
          <input type="hidden" name="id" value={book.id} />
          <textarea name="notes" defaultValue={book.notes} />
          <button type="submit">Save notes</button>
        </form>
      </section>
    </main>
  );
}

